async function getTable(name) {
  const comp = game.packs.get('mausritter.tables');
  if (!comp) {
    ui.notifications.warn(`Компендіум "${compendium_label}" не знайдено.`);
    return null;
  }
  const tables = await comp.getDocuments();
  const table = tables.find(t => t.name === name);
  if (!table) ui.notifications.warn(`Таблиця "${name}" не знайдена.`);
  return table || null;
}

