// Стилі кнопок
function btnStyle(bg = '#dcdcdc') {
  return `
    width: 100%;
    padding: 6px;
    font-size: 1.05em;
    background-color: ${bg};
    border: 1px solid #aaa;
    color: #333;
    border-radius: 4px;
  `;
}

async function hexType(hexType) {
  const map = {
    'Сільська місцевість': 'Гекс - Сільська місцевість',
    'Ліс': 'Гекс - Ліс',
    'Річка': 'Гекс - Річка',
    'Людське місто': 'Гекс - Людське місто'
  };

  let rollNote = '';

  if (hexType === "Випадковий") {
    const typeTable = await drawFromTable("Гекс - Типи");
    if (!typeTable) return;

    const roll = await new Roll(typeTable.formula).evaluate();
    const results = await typeTable.getResultsForRoll(roll.total);
    const resultText = (results[0]?.name ?? results[0]?.description ?? "")?.trim();

    if (!resultText) {
      ui.notifications.warn("Не вдалося визначити результат кидка з таблиці 'Гекс - Типи'.");
      return;
    }

    hexType = resultText;
    rollNote = `<small><i>(Тип визначено випадково: ${typeTable.formula} = ${roll.total})</i></small><br/>`;
  }

  const tableName = map[hexType];
  if (!tableName) {
    ui.notifications.warn(`Невідомий тип гекса: "${hexType}".`);
    return;
  }

  const hexTable = await drawFromTable(tableName);
  const landmarkTable = await drawFromTable("Гекс - Деталі орієнтирів");

  if (!hexTable || !landmarkTable) return;

  const hexRoll = await hexTable.roll();
  const landmarkRoll = await landmarkTable.roll();

  const hexContents = (hexRoll.results[0]?.name ?? hexRoll.results[0]?.description ?? "");
  const hexDetails = (landmarkRoll.results[0]?.name ?? landmarkRoll.results[0]?.description ?? "");

  const message = `
    <h2>${hexType}:</h2>
    ${rollNote}
    <b>Орієнтир:</b> ${hexContents}<br/>
    <b>Деталі:</b> <i>${hexDetails}</i><br/>
  `;

  ChatMessage.create({
    content: message,
    whisper: ChatMessage.getWhisperRecipients("GM")
  });
}

async function drawFromTable(tableName) {
  const compendium = game.packs.find(p =>
    p.documentName === 'RollTable' && p.metadata.label === compendium_label
  );

  if (!compendium) {
    ui.notifications.warn(`Компендіум "${compendium_label}" не знайдено.`);
    return null;
  }

  const tables = await compendium.getDocuments();
  const table = tables.find(t => t.name === tableName);

  if (!table) {
    ui.notifications.warn(`Таблиця "${tableName}" не знайдена.`);
    return null;
  }

  return table;
}

