/* Допоміжні функції */
async function drawFromTable(tableName) {
  const compendium = game.packs.get('mausritter.tables');
  if (!compendium) {
    ui.notifications.warn(`Компендіум "${compendium_label}" не знайдено.`);
    return '';
  }

  const tables = await compendium.getDocuments();
  const table = tables.find(p => p.name === tableName);

  if (!table) {
    ui.notifications.warn(`Таблиця "${tableName}" не знайдена.`);
    return '';
  }

  const roll = await table.roll();
  let resultText = (roll.results[0]?.name ?? roll.results[0]?.description ?? "");

  // Обробка формули [[/r ...]]
  const match = resultText.match(/\[\[\/r ([^\]]+)\]\]/);
  if (match) {
    const formula = match[1];
    const rollResult = new Roll(formula);
    await rollResult.evaluate();
    const total = rollResult.total;

    // Заміна [[/r ...]] на **total** (формула)
    resultText = resultText.replace(match[0], `<b>${total}</b> (${formula})`);
  }


  return resultText;
}

async function attrRoll() {
  const roll = new Roll('2d6');
  await roll.evaluate();
  return roll.total;
}

async function healthRoll() {
  const roll = new Roll('1d6');
  await roll.evaluate();
  return roll.total;
}

