(async () => {
  /**
   * Функція кидка 3d6 і підсумовування двох найбільших результатів.
   * Використовується для генерації основних атрибутів персонажа.
   * @returns {Promise<number>} - сума двох найбільших кубиків
   */
  async function rollAttribute() {
    // Кидаємо 3 шестигранних кубики
    const roll = await new Roll("3d6").evaluate();
    // Витягуємо результати кидків у масив
    const diceResults = roll.terms[0].results.map(r => r.result);
    // Сортуємо результати за спаданням
    diceResults.sort((a, b) => b - a);
    // Повертаємо суму двох найбільших кубиків
    return diceResults[0] + diceResults[1];
  }

  /**
   * Функція кидка на випадковий результат із таблиці у компендіумі.
   * Знаходить таблицю за назвою в компендіумі з назвою compendium_label.
   * Кидає таблицю та повертає текст першого результату.
   * @param {string} tableName - Назва таблиці в компендіумі
   * @returns {Promise<string>} - текст обраного рядка таблиці
   */
  async function rollFromTable(tableName) {
    // Знаходимо компендіум із таблицями за назвою (documentName) і міткою (label)
    const compendium = game.packs.get('mausritter.tables');
    if (!compendium) {
      // Якщо компендіум не знайдено — виводимо повідомлення користувачу
      ui.notifications.warn(`Компендіум "${compendium_label}" не знайдено.`);
      return "";
    }
    // Отримуємо всі таблиці з компендіума
    const tables = await compendium.getDocuments();
    // Знаходимо таблицю за ім’ям
    const table = tables.find(t => t.name === tableName);
    if (!table) {
      // Якщо таблицю не знайдено — виводимо повідомлення
      ui.notifications.warn(`Таблиця "${tableName}" не знайдена.`);
      return "";
    }
    // Кидаємо кубик для таблиці, отримуємо результат
    const roll = await table.roll();
    // Повертаємо текст першого результату
    return (roll.results[0]?.name ?? roll.results[0]?.description ?? "");
  }

  /**
   * Функція пошуку передісторії персонажа за двома параметрами: значенням здоров'я (pz) та зерняток (seeds).
   * Використовується для вибору початкової передісторії та відповідних предметів.
   * @param {number} health - значення здоров'я персонажа (pz)
   * @param {number} pips - значення зерняток (seeds)
   * @returns {object|undefined} - об’єкт передісторії або undefined, якщо не знайдено
   */
  function findBackground(health, pips) {
    return backgrounds.find(b => b.pz === health && b.seeds === pips);
  }

  /**
   * Функція для додавання предмета до актора (персонажа) за назвою.
   * Перевіряє кілька компендіумів (спорядження, зброя, закляття, обладунки).
   * Якщо предмет знайдено, додає його до актора.
   * @param {Actor} actor - об’єкт актора, до якого додаємо предмет
   * @param {string} itemName - назва предмета для додавання
   * @returns {Promise<boolean>} - true, якщо предмет додано, false — ні
   */
  async function addItemToActor(actor, itemName) {
    // Перелік компендіумів, де шукаємо предмет
    const compendiumIds = ["mausritter.gear", "mausritter.weapons", "mausritter.spells", "mausritter.armor"];
    // Перебираємо компендіуми один за одним
    for (const packId of compendiumIds) {
      // Знаходимо компендіум за типом "Item" та міткою
      const compendium = game.packs.get(packId);
      if (!compendium) continue; // якщо немає компендіума такого типу — пропускаємо
      // Отримуємо всі предмети з компендіума
      const items = await compendium.getDocuments();
      // Шукаємо предмет з точною назвою (без урахування регістру)
      const item = items.find(i => i.name.toLowerCase() === itemName.toLowerCase());
      if (item) {
        // Додаємо предмет до актора як вкладений документ
        await actor.createEmbeddedDocuments("Item", [item.toObject()]);
        return true; // предмет додано успішно
      }
    }
    // Якщо предмет не знайдено у жодному компендіумі — показуємо попередження
    ui.notifications.warn(`Предмет "${itemName}" не знайдено в компендіумах.`);
    return false;
  }

  // Об’єкт, який містить додаткові предмети, що додаються при виборі певної зброї
  const weaponExtras = {
    "Лук": ["Стріли, сагайдак"],
    "Праща": ["Каміння, мішечок"]
  };

  /**
   * Відкриває діалог для вибору зброї з компендіума "Зброя".
   * Після вибору повертає об’єкт Item або null при відміні.
   * @returns {Promise<Item|null>}
   */
