    const items = await compendium.getDocuments();

    // Створюємо HTML-опції для select зі списком зброї
    let optionsHTML = items.map(i => `<option value="${i.id}">${i.name}</option>`).join("");

    // Повертаємо Promise, який вирішиться після вибору або відміни
    return new Promise((resolve) => {
      // Створюємо діалог із селектом
      const dialog = new DialogClass({
        title: "Вибір зброї",
        content: `<p>Оберіть зброю зі списку:</p><select id="weapon-select" style="width:100%">${optionsHTML}</select>`,
        buttons: {
