            label: "Додати",
            callback: (html) => {
              // Отримуємо обране id зброї
              const selectedId = html.find("#weapon-select").val();
              // Знаходимо об’єкт зброї за id
              const selectedItem = items.find(i => i.id === selectedId);
              resolve(selectedItem);
            }
          },
          cancel: {
            label: "Відміна",
            callback: () => resolve(null)
          }
        },
        default: "ok",
        close: () => resolve(null)
      });

      // Затримка для плавного показу діалогу та виправлення z-index для роботи поверх інших вікон
      setTimeout(() => {
        dialog.render(true, { focus: true });
        setTimeout(() => {
          const el = dialog.element?.get(0);
          if (el) el.style.zIndex = 9999;
        }, 50);
      }, 300);
    });
  }

  /**
   * Функція для додавання вибраного предмета до актора.
   * Якщо для зброї є додаткові предмети — додає і їх.
   * Виводить повідомлення про додану зброю та супутні предмети.
   * @param {Actor} actor - персонаж, до якого додаємо
   * @param {Item} item - вибраний предмет зброї
   * @returns {Promise<boolean>} - true, якщо додано, false якщо ні
   */
  async function addSelectedItemToActor(actor, item) {
    if (!item) return false;
    // Додаємо основний предмет (зброю)
    await actor.createEmbeddedDocuments("Item", [item.toObject()]);

    // Шукаємо додаткові предмети для вибраної зброї
    const extras = weaponExtras[item.name];
    if (extras && extras.length) {
      // Додаємо кожен додатковий предмет
      for (const extraName of extras) {
        await addItemToActor(actor, extraName);
      }
      // Повідомлення з переліком додаткових предметів
      ui.notifications.info(`🗡️ Обрана зброя: ${item.name} (+ ${extras.join(", ")})`);
    } else {
      // Повідомлення про зброю без додаткових предметів
      ui.notifications.info(`🗡️ Обрана зброя: ${item.name}`);
    }
    return true;
  }

  // Початок логіки генерації персонажа

  // Генеруємо ім'я (перше + прізвище) персонажа, кидаючи відповідні таблиці
  const firstName = await rollFromTable("Мишачі Імена");
  const lastName = await rollFromTable("Мишачі Прізвища");
  const fullName = [firstName, lastName].filter(Boolean).join(" ").trim() || "Мишеня";

  // Генеруємо основні атрибути: сила, спритність, воля
  const strength = await rollAttribute();
  const dexterity = await rollAttribute();
  const will = await rollAttribute();

  // Визначаємо найбільше значення серед атрибутів для подальшої логіки
  const highestAttr = Math.max(strength, dexterity, will);

  // Генеруємо показники здоров'я (pz) і зерняток (seeds)
  const health = (await new Roll("1d6").evaluate()).total;
  const pips = (await new Roll("1d6").evaluate()).total;

  // Генеруємо зовнішні ознаки: сузір'я, колір хутра, візерунок, фізичні деталі
  const birthsign = await rollFromTable('Мишачі Сузір’я');
  const coatColor = await rollFromTable('Мишаче хутро - Забарвлення');
  const coatPattern = await rollFromTable('Мишаче хутро - Візерунок');
  const physicalDetail = await rollFromTable('Мишачі Фізичні деталі');
  const coat = `${coatColor}, ${coatPattern}`;

  // Визначаємо основну передісторію персонажа за показниками здоров'я і зерняток
  const background = findBackground(health, pips);
  if (!background) {
    // Якщо передісторію не знайдено — показуємо попередження
    ui.notifications.warn(`⚠️ Основна передісторія не знайдена. ПЗ: ${health}, Зернятка: ${pips}`);
  }

  // Змінна для можливої додаткової передісторії (у випадку слабких атрибутів)
  let extraBackground = null;

  // Створюємо нового персонажа (актора) у системі з усіма згенерованими даними
  const actor = await Actor.create({
    name: fullName,
    type: "character",
    prototypeToken: { name: fullName },
    system: {
      stats: {
        strength: { value: strength, max: strength },
        dexterity: { value: dexterity, max: dexterity },
        will: { value: will, max: will }
      },
      health: { value: health, max: health },
      pips: { value: pips },
      description: {
        birthsign,
        background: background ? background.name : "",
        coat,
        look: physicalDetail
      },
      notes: ""
    }
  });

  if (!actor) {
    ui.notifications.error("Не вдалося створити персонажа. Перевірте дані генератора та компендіуми.");
    return;
  }

  // Додаємо предмети, які належать основній передісторії
  if (background) {
    await addItemToActor(actor, background.a);
    await addItemToActor(actor, background.b);
  }

  // Додаємо базові стартові предмети, які отримує кожен персонаж
  await addItemToActor(actor, "Смолоскипи");
  await addItemToActor(actor, "Пайки");

  // Відкриваємо лист персонажа для перегляду після створення
  await actor.sheet.render(true);

  /**
   * Контролер, щоб вибір зброї відбувався лише один раз.
   * Після вибору зброї також пропонує обмін характеристик.
   */
  let weaponChoiceStarted = false;
  async function proceedWeaponChoice() {
    if (weaponChoiceStarted) return;
    weaponChoiceStarted = true;

    // Відкриваємо діалог вибору зброї
    const weapon = await chooseWeapon();
    // Додаємо вибрану зброю (та додаткові предмети, якщо є)
    await addSelectedItemToActor(actor, weapon);

    // Після зброї пропонуємо обмін атрибутів
    await offerSwapAttributes();
  }

  /**
   * Логіка додавання додаткової передісторії і предметів,
   * якщо найвищий атрибут <= 9.
   * При дуже слабких характеристиках (<=7) — даємо обидва предмети,
   * при атрибутах 8-9 — даємо вибір одного.
   */
  if (highestAttr <= 9) {
    // Перекидаємо показники здоров'я та зерняток для додаткової передісторії
    const rerollHealth = (await new Roll("1d6").evaluate()).total;
    const rerollPips = (await new Roll("1d6").evaluate()).total;
    extraBackground = findBackground(rerollHealth, rerollPips);

    if (extraBackground) {
      if (highestAttr <= 7) {
        // Діалог із автоматичним додаванням двох предметів без вибору
        const dialog = new DialogClass({
          title: "Додаткові предмети",
          content: `<p>Ваші характеристики не більше 7.</p>
                    <p><b>Додаткова передісторія:</b> ${extraBackground.name}</p>
                    <p><b>ПЗ:</b> ${rerollHealth}, <b>Зернятка:</b> ${rerollPips}</p>
                    <p>Отримуєте два додаткових предмети:</p>
                    <p><b>${extraBackground.a}, ${extraBackground.b}</b></p>`,
          buttons: {
            ok: {
              label: "Добре",
              callback: async () => {
                // Додаємо обидва предмети
                await addItemToActor(actor, extraBackground.a);
                await addItemToActor(actor, extraBackground.b);
                ui.notifications.info(`📜 Додаткова передісторія: ${extraBackground.name} — отримано ${extraBackground.a} і ${extraBackground.b}`);
                // Після цього починаємо вибір зброї
                await proceedWeaponChoice();
              }
            }
          },
          default: "ok"
        });

        // Рендер діалогу із затримкою і налаштуванням z-index
        setTimeout(() => {
          dialog.render(true, { focus: true });
          setTimeout(() => {
            const el = dialog.element?.get(0);
            if (el) el.style.zIndex = 9999;
          }, 50);
        }, 300);
      } else {
        // Якщо атрибути 8-9 — даємо вибір одного предмета з двох
        const dialog = new DialogClass({
          title: "Додатковий предмет",
          content: `<p>Ваші характеристики не більше 9.</p>
                    <p><b>Додаткова передісторія:</b> ${extraBackground.name}</p>
                    <p><b>ПЗ:</b> ${rerollHealth}, <b>Зернятка:</b> ${rerollPips}</p>
                    <p>Виберіть один з додаткових предметів:</p>
                    <button class="item-a">${extraBackground.a}</button>
                    <button class="item-b">${extraBackground.b}</button>`,
          buttons: {}, // кастомні кнопки в контенті
          render: html => {
            // При натисканні на кнопку додаємо відповідний предмет
            html.find(".item-a").click(async () => {
              await addItemToActor(actor, extraBackground.a);
              ui.notifications.info(`📜 Додаткова передісторія: ${extraBackground.name} — отримано ${extraBackground.a}`);
              dialog.close();
              await proceedWeaponChoice();
            });
            html.find(".item-b").click(async () => {
              await addItemToActor(actor, extraBackground.b);
              ui.notifications.info(`📜 Додаткова передісторія: ${extraBackground.name} — отримано ${extraBackground.b}`);
              dialog.close();
              await proceedWeaponChoice();
            });
          },
          close: async () => await proceedWeaponChoice()
        });

        // Відображення діалогу з затримкою і виправленням z-index
        setTimeout(() => {
          dialog.render(true, { focus: true });
          setTimeout(() => {
            const el = dialog.element?.get(0);
            if (el) el.style.zIndex = 9999;
          }, 50);
        }, 300);
      }
    } else {
      // Якщо додаткову передісторію не знайдено — просто починаємо вибір зброї
      await proceedWeaponChoice();
    }
  } else {
    // Якщо атрибути вище 9 — одразу вибір зброї без додаткової передісторії
    await proceedWeaponChoice();
  }

  // Якщо додаткова передісторія була визначена — оновлюємо поле опису персонажа
  if (extraBackground) {
    await actor.update({
      "system.description.background": `${background ? background.name : ""} (${extraBackground.name})`
    });
  }

  /**
   * Функція пропонує користувачу обміняти дві характеристики між собою.
   * Відкривається діалог з двома випадаючими списками для вибору.
   * Якщо вибрані різні характеристики — обмінює їх значення.
   * @returns {Promise<boolean>} - true, якщо обмін відбувся, false — ні
   */
  async function offerSwapAttributes() {
    return new Promise((resolve) => {
      const options = ["СИЛ", "МОТ", "ВОЛ"]; // Варіанти для вибору: Сила, Спритність, Воля
      // Ключі відповідно до властивостей у системі актора
      const attrKeys = {
        "СИЛ": "strength",
        "МОТ": "dexterity",
        "ВОЛ": "will"
      };

      // HTML контент діалогу з двома селектами і підказкою
      const content = `
        <div style="display:flex;gap:5px;align-items:center;">
          <select id="attr1">${options.map(o => `<option>${o}</option>`).join("")}</select>
          <span>⇄</span>
          <select id="attr2">${options.map(o => `<option>${o}</option>`).join("")}</select>
        </div>
        <small>Обери дві різні характеристики або натисни «Залишити»</small>
      `;

      // Створюємо діалог
      const dialog = new DialogClass({
        title: "Обмін характеристик",
        content,
        buttons: {
          swap: {
            label: "Обміняти",
            callback: async (html) => {
              // Отримуємо обрані варіанти
              const a1 = html.find("#attr1").val();
              const a2 = html.find("#attr2").val();

              // Якщо обрано однакові характеристики — показуємо попередження і не робимо обмін
              if (a1 === a2) {
                ui.notifications.warn("Оберіть різні характеристики.");
                resolve(false);
                return;
              }

              // Отримуємо ключі системних властивостей для вибраних атрибутів
              const k1 = attrKeys[a1];
              const k2 = attrKeys[a2];
              // Отримуємо поточні значення обраних атрибутів
              const v1 = actor.system.stats[k1].value;
              const v2 = actor.system.stats[k2].value;

              // Оновлюємо актора, помінявши значення між атрибутами
              await actor.update({
                [`system.stats.${k1}.value`]: v2,
                [`system.stats.${k1}.max`]: v2,
                [`system.stats.${k2}.value`]: v1,
                [`system.stats.${k2}.max`]: v1
              });

              // Сповіщаємо про успішний обмін
              ui.notifications.info(`🔄 ${a1} ⇄ ${a2}`);
              resolve(true);
            }
          },
          cancel: {
            label: "Залишити",
            callback: () => resolve(false)
          }
        },
        default: "cancel"
      });

      // Рендер діалогу з затримкою та виправленням z-index для коректного відображення
      setTimeout(() => {
        dialog.render(true, { focus: true });
        setTimeout(() => {
          const el = dialog.element?.get(0);
          if (el) el.style.zIndex = 9999;
        }, 50);
      }, 300);
    });
  }
})();
